begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id) values ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb');
select is((public.ai_account('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa')->>'balance')::integer,10,'welcome grants ten');
select is((public.ai_account('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa')->>'balance')::integer,10,'welcome never repeats');
select ok(not has_table_privilege('authenticated','public.ai_credit_accounts','UPDATE'),'client cannot edit balance');
select ok(not has_function_privilege('authenticated','public.ai_grant_paid(uuid,text)','EXECUTE'),'client cannot grant credits');
select ok(not has_table_privilege('authenticated','public.ai_word_requests','SELECT'),'client cannot read another user request');
select is(public.ai_reserve('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','11111111-1111-4111-8111-111111111111','{"term":"test"}')->>'status','reserved','reserve succeeds');
select is((public.ai_account('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa')->>'balance')::integer,9,'reservation costs one');
select is(public.ai_reserve('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','11111111-1111-4111-8111-111111111111','{"term":"test"}')->>'status','pending','duplicate is pending');
select is((public.ai_account('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa')->>'balance')::integer,9,'retry never double charges');
select is(public.ai_reserve('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','11111111-1111-4111-8111-111111111111','{"term":"different"}')->>'status','conflict','same id cannot change input');
select is(public.ai_finish('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','11111111-1111-4111-8111-111111111111','{"definition":"test"}','{}')->>'status','completed','completion succeeds');
select is(public.ai_reserve('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','11111111-1111-4111-8111-111111111111','{"term":"test"}')->'suggestion','{"definition":"test"}'::jsonb,'retry recovers saved output');
select is((public.ai_finish('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','11111111-1111-4111-8111-111111111111',null,null)->>'balance')::integer,9,'late failure cannot refund a completed result');
select public.ai_reserve('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','22222222-2222-4222-8222-222222222222','{}');
select is((public.ai_finish('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','22222222-2222-4222-8222-222222222222',null,null)->>'balance')::integer,9,'failure refunds once');
select is((public.ai_finish('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','22222222-2222-4222-8222-222222222222',null,null)->>'balance')::integer,9,'second failure does not refund twice');
select public.ai_reserve('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','33333333-3333-4333-8333-333333333333','{}');
update public.ai_word_requests set expires_at=now()-interval '1 second' where request_id='33333333-3333-4333-8333-333333333333';
select is((public.ai_account('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa')->>'balance')::integer,9,'abandoned reservation expires and refunds');
select is(public.ai_finish('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','33333333-3333-4333-8333-333333333333','{}','{}')->>'status','failed','late worker cannot complete an expired reservation');
select is((public.ai_grant_paid('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',repeat('a',64))->>'balance')::integer,49,'upgrade adds forty preserving prior spend');
select is((public.ai_grant_paid('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',repeat('a',64))->>'balance')::integer,49,'restore does not repeat bonus');
select is((public.ai_grant_paid('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',repeat('a',64))->>'balance')::integer,10,'same purchase cannot grant another account');
update public.ai_credit_accounts set balance=0 where user_id='bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb';
select is(public.ai_reserve('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','44444444-4444-4444-8444-444444444444','{}')->>'status','empty','zero balance rejects');
set local role authenticated;
select set_config('request.jwt.claim.sub','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',true);
select is((select count(*)::integer from public.ai_credit_accounts),1,'RLS exposes only own wallet');
reset role;
delete from auth.users where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa';
select is((select count(*)::integer from public.ai_word_requests),0,'account deletion clears requests');
select is((public.ai_grant_paid('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb',repeat('a',64))->>'balance')::integer,0,'deleting original owner does not release purchase bonus');
select * from finish();
rollback;
